(function(){'use strict';const API=(window.BTTAuth&&window.BTTAuth.API)||'https://api.aallyn.net';async function postJSON(path,body){const res=await fetch(API+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),});let data=null;try{data=await res.json();}catch(_){}
return{ok:res.ok,status:res.status,data};}
function t(s){return window.BTTi18n&&window.BTTi18n.t?window.BTTi18n.t(s):s;}
function errorMessage(data){if(!data)return null;if(data.error&&data.error.message)return data.error.message;if(typeof data.detail==='string')return data.detail;if(Array.isArray(data.detail)&&data.detail.length){const first=data.detail[0];return first.msg||JSON.stringify(first);}
return null;}
function wireForgotForm(){const $form=document.getElementById('forgot-form');if(!$form)return;const $email=document.getElementById('forgot-email');const $err=document.getElementById('forgot-error');const $ok=document.getElementById('forgot-success');const $submit=document.getElementById('forgot-submit');const $captcha=document.getElementById('forgot-captcha');let getCaptchaToken=()=>null;if($captcha&&window.BTTAuth&&window.BTTAuth.mountCaptcha){window.BTTAuth.mountCaptcha($captcha).then((fn)=>{getCaptchaToken=fn;});}
$form.addEventListener('submit',async(e)=>{e.preventDefault();$err.hidden=true;$ok.hidden=true;$submit.disabled=true;try{const r=await postJSON('/v1/site-auth/forgot-password',{email:$email.value.trim(),captcha_token:getCaptchaToken(),});if(!r.ok){$err.textContent=errorMessage(r.data)||t('Something went wrong. Try again in a minute.');$err.hidden=false;return;}
$ok.textContent=(r.data&&r.data.message)||t("Check your inbox - if that email's registered, a reset link is on its way.");$ok.hidden=false;}finally{$submit.disabled=false;}});}
function wireResetForm(){const $form=document.getElementById('reset-form');if(!$form)return;const $noToken=document.getElementById('reset-no-token');const $pw=document.getElementById('reset-password');const $confirm=document.getElementById('reset-password-confirm');const $err=document.getElementById('reset-error');const $ok=document.getElementById('reset-success');const $submit=document.getElementById('reset-submit');const params=new URLSearchParams(location.search);const token=params.get('token');if(!token){$form.hidden=true;if($noToken)$noToken.hidden=false;return;}
$form.addEventListener('submit',async(e)=>{e.preventDefault();$err.hidden=true;$ok.hidden=true;if($pw.value!==$confirm.value){$err.textContent=t("The two passwords don't match.");$err.hidden=false;return;}
$submit.disabled=true;try{const r=await postJSON('/v1/site-auth/reset-password',{token,new_password:$pw.value,});if(!r.ok){$err.textContent=errorMessage(r.data)||t('Reset failed.');$err.hidden=false;return;}
$ok.textContent=(r.data&&r.data.message)||t('Your password has been reset. Redirecting to sign in…');$ok.hidden=false;setTimeout(()=>{location.href='/login';},1800);}finally{$submit.disabled=false;}});}
function boot(){wireForgotForm();wireResetForm();}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',boot);}else{boot();}})();